StyleSheet:
/* Large tonal surfaces with pill actions and deliberate whitespace. */
.theme { skin: studio; }
.bar { height: 52px; padding: 6px; gap: 6px; border-radius: 28px; border-width: 0px; }
.tab { height: 40px; padding: 0px 22px; margin: 0px; border-radius: 24px; border-width: 0px; font-size: 14px; font-weight: bold; indicator: none; selected-background: accent-soft; }
.menu { width: 314px; padding: 14px; gap: 6px; border-radius: 28px; border-width: 0px; box-shadow: 0px 8px 28px rgba(0,0,0,0.18); }
.menu-item { height: 46px; padding: 0px 16px; margin: 0px; border-radius: 22px; border-width: 0px; icon-size: 30px; }
.button { min-height: 40px; padding: 8px 24px; border-radius: 28px; border-width: 0px; font-size: 14px; font-weight: bold; }
.input { min-height: 40px; padding: 8px 16px; border-radius: 18px; border-width: 0px; background: var(--accent-soft); }
.card { padding: 24px; gap: 16px; border-radius: 28px; border-width: 0px; }
.sidebar-item { height: 44px; padding: 0px 18px; margin: 3px 0px; border-radius: 24px; font-weight: semibold; }
.window { border-radius: 16px; border-width: 0px; }
.titlebar { height: 44px; background: transparent; border-width: 0px; }
.sidebar { border-radius: 24px; border-width: 0px; }
.page { background: transparent; border-width: 0px; }
.toast { border-radius: 28px; border-width: 0px; }
